WITH scored AS (SELECT *, AVG(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS quantity_avg_6_prior, AVG(quantity) OVER w_hist AS quantity_avg_6, CUME_DIST() OVER w_hist_2 AS quantity_cume_dist FROM inventory WINDOW w_hist AS (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW), w_hist_2 AS (PARTITION BY product_id ORDER BY quantity DESC NULLS FIRST)) SELECT id, quantity, quantity_avg_6_prior, quantity_avg_6, quantity_cume_dist FROM scored ORDER BY id DESC LIMIT 5;
